import{_ as a,o,c as t,a2 as r}from"./chunks/framework.BTLSZHNB.js";const p=JSON.parse('{"title":"WorkerCustomDomain — takoform_worker_custom_domain","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/worker-custom-domain.md","filePath":"proposals/edge/worker-custom-domain.md"}'),i={name:"proposals/edge/worker-custom-domain.md"};function n(s,e,c,d,h,m){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="workercustomdomain-—-takoform-worker-custom-domain" tabindex="-1">WorkerCustomDomain — <code>takoform_worker_custom_domain</code> <a class="header-anchor" href="#workercustomdomain-—-takoform-worker-custom-domain" aria-label="Permalink to &quot;WorkerCustomDomain — `takoform_worker_custom_domain`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A team serves its worker on its own DNS hostname over HTTPS. External clients reach the worker&#39;s active deployment at that hostname; certificates and TLS termination are the host&#39;s obligation, never portable state.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>attachment</code>. Inward activation is an attachment resource, never a binding (decision 0010). Deleting the attachment detaches the hostname and never deletes the worker.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p><code>hostname</code> is one dotted DNS name; <code>worker</code> is the Module Worker whose active deployment answers it. Both are immutable: changing either replaces the attachment. Requests on the hostname invoke the worker&#39;s <code>fetch</code> handler.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Hostname attachment is one complete observable fact: which name reaches which worker. Certificate mechanics differ per host and are deliberately outside the contract.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>Path-pattern or zone-scoped routes carry matching semantics beyond a whole hostname and are a separate attachment Form (<code>WorkerRoute</code> in the family plan, <a href="./../../spec/form-families.html">spec/form-families.md</a>).</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Two attachments claiming one hostname must conflict deterministically. Deleting the worker while the attachment exists must fail with <code>dependency_in_use</code>. Import must recover hostname and worker exactly.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The custom-domain attachment of a proven edge platform, with its certificate provisioning kept host-side.</p>',19)])])}const u=a(i,[["render",n]]);export{p as __pageData,u as default};
